// ── Delivery & expiry policy (task #581) ──────────────────────────────────
// A contract that exceeds this multiple of its quoted durationTicks without
// reaching 100% is scrapped ("expired") instead of squatting in the active
// queue charging retainer fees forever. Worst-case honest rolls (slowest
// contractor × qualityFirst policy, heavy delay rolls) still finish under
// 2× quote, so only contracts stalled on materials ever hit 3×.
export const CONTRACT_EXPIRY_MULTIPLIER = 3;

// When a contract is scrapped, the contractor returns a quarter of the
// original upfront deposit, scaled by the unfinished share of the work.
// Retainer fees and the rest of the upfront deposit remain written off as the
// cost of the failed procurement. Keeping this rule tied to the upfront
// deposit (rather than totalPaid) prevents long-stalled awards from creating
// a larger refund merely because they continued billing before expiry.
export const CONTRACT_EXPIRY_RECOVERY_RATE = 0.25;

export function computeContractExpiryRecovery(upfrontCost: number, progress: number): number {
  if (!Number.isFinite(upfrontCost) || !Number.isFinite(progress) || upfrontCost <= 0) return 0;
  const unfinishedShare = 1 - Math.min(100, Math.max(0, progress)) / 100;
  return Math.floor(upfrontCost * CONTRACT_EXPIRY_RECOVERY_RATE * unfinishedShare);
}

export type ContractGoodsCommitmentForecast = {
  activeGoodsPerTick: number;
  candidateGoodsPerTick: number;
  combinedGoodsPerTick: number;
  netGoodsIncome: number;
  exceedsNetIncome: boolean;
};

export function forecastContractGoodsCommitment(
  activeContracts: Array<Pick<ContractInstance, "defId" | "status">> | undefined | null,
  candidate: Pick<ContractDef, "materialPerTick">,
  netGoodsIncome: number,
): ContractGoodsCommitmentForecast {
  const activeGoodsPerTick = (activeContracts ?? []).reduce((sum, contract) => {
    if (contract.status !== "active") return sum;
    return sum + (CONTRACT_TEMPLATES_MAP[contract.defId]?.materialPerTick.goods ?? 0);
  }, 0);
  const candidateGoodsPerTick = candidate.materialPerTick.goods ?? 0;
  const combinedGoodsPerTick = activeGoodsPerTick + candidateGoodsPerTick;

  return {
    activeGoodsPerTick,
    candidateGoodsPerTick,
    combinedGoodsPerTick,
    netGoodsIncome,
    exceedsNetIncome: combinedGoodsPerTick > 0 && combinedGoodsPerTick > netGoodsIncome,
  };
}

// Since expiry landed, the completedContracts archive holds BOTH fulfilled
// awards and "expired" scraps. Progression/stat consumers (achievements,
// Steam stats, propaganda, run summary) must count fulfilled awards only —
// never raw archive length, or failed contracts would farm progress.
// Anything not explicitly "expired" counts, so legacy archives (all
// status "completed") keep their totals. Tolerant param type: steamBridge's
// lite save shape passes loosely-typed entries.
export function countFulfilledContracts(archive: Array<{ status?: string }> | undefined | null): number {
  let n = 0;
  for (const c of archive ?? []) {
    if (c && c.status !== "expired") n++;
  }
  return n;
}

// Local humanizer (contracts.ts stays a leaf module — no value imports).
// workerHousingStacks → "Worker Housing Stacks", wild_meat → "Wild Meat".
function humanizeEffectKey(key: string): string {
  return key
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/[_-]+/g, " ")
    .split(/\s+/)
    .filter(Boolean)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");
}

// One-line "what actually arrived" summary for delivery confirmations
// (inbox + news ticker). Lists tangible goods first, civic effects last.
export function summarizeCompletionEffects(def: ContractDef): string {
  const parts: string[] = [];
  for (const [k, v] of Object.entries(def.completionEffects.buildings ?? {})) {
    if (typeof v === "number" && v !== 0) parts.push(`${v}× ${humanizeEffectKey(k)}`);
  }
  for (const [k, v] of Object.entries(def.completionEffects.units ?? {})) {
    if (typeof v === "number" && v !== 0) parts.push(`${v}× ${humanizeEffectKey(k)}`);
  }
  for (const [k, v] of Object.entries(def.completionEffects.resources ?? {})) {
    if (typeof v === "number" && v !== 0) parts.push(`+${v} ${humanizeEffectKey(k).toLowerCase()}`);
  }
  for (const [k, v] of Object.entries(def.completionEffects.stockpiles ?? {})) {
    if (typeof v === "number" && v !== 0) parts.push(`+${v} ${humanizeEffectKey(k).toLowerCase()}`);
  }
  for (const [k, v] of Object.entries(def.completionEffects.cityStats ?? {})) {
    if (typeof v === "number" && v !== 0) parts.push(`${v > 0 ? "+" : ""}${v} ${humanizeEffectKey(k).toLowerCase()}`);
  }
  return parts.join(", ");
}

